#!/usr/bin/env python3
import sys
import sqlite3
import json
import os
import re

def quote_csv(v):
    if v is None:
        return ""
    s = str(v)
    if ',' in s or '"' in s or '\n' in s or '\r' in s:
        s = s.replace('"', '""')
        return f'"{s}"'
    return s

def format_output(cols, rows, options):
    mode = options['mode']
    header = options['header']
    nullvalue = options['nullvalue']
    sep = options['separator']

    if mode == 'list':
        if header:
            print(sep.join(cols))
        for row in rows:
            print(sep.join([str(v) if v is not None else nullvalue for v in row]))
    elif mode == 'csv':
        if header:
            print(",".join([quote_csv(c) for c in cols]))
        for row in rows:
            print(",".join([quote_csv(v) for v in row]))
    elif mode == 'json':
        res = []
        for row in rows:
            d = {}
            for i, v in enumerate(row):
                d[cols[i]] = v
            res.append(d)
        print(json.dumps(res, separators=(',', ':')))
    elif mode == 'column':
        if not rows:
            if header:
                print("  ".join(cols))
            return
        widths = [len(c) for c in cols]
        for row in rows:
            for i, v in enumerate(row):
                widths[i] = max(widths[i], len(str(v if v is not None else nullvalue)))

        if header or True: # Column mode always seems to show something like headers? No, wait.
            # SQLite's column mode is a bit complex.
            header_line = ""
            dash_line = ""
            for i, c in enumerate(cols):
                w = widths[i]
                header_line += c.ljust(w) + "  "
                dash_line += ("-" * w) + "  "
            print(header_line.rstrip())
            print(dash_line.rstrip())

        for row in rows:
            line = ""
            for i, v in enumerate(row):
                val = str(v if v is not None else nullvalue)
                if isinstance(v, (int, float)):
                    line += val.rjust(widths[i]) + "  "
                else:
                    line += val.ljust(widths[i]) + "  "
            print(line.rstrip())
    elif mode == 'table':
        if not rows: return
        widths = [len(c) for c in cols]
        for row in rows:
            for i, v in enumerate(row):
                widths[i] = max(widths[i], len(str(v if v is not None else nullvalue)))

        sep_line = "+" + "+".join(["-" * (w + 2) for w in widths]) + "+"
        print(sep_line)
        print("| " + " | ".join([cols[i].ljust(widths[i]) for i in range(len(cols))]) + " |")
        print(sep_line)
        for row in rows:
            line = "| "
            for i, v in enumerate(row):
                val = str(v if v is not None else nullvalue)
                line += val.ljust(widths[i]) + " | "
            print(line.rstrip())
        print(sep_line)
    elif mode == 'box':
        # Simplistic box mode
        if not rows: return
        widths = [len(c) for c in cols]
        for row in rows:
            for i, v in enumerate(row):
                widths[i] = max(widths[i], len(str(v if v is not None else nullvalue)))
        print("╭─" + "─┬─".join(["─" * w for w in widths]) + "─╮")
        print("│ " + " │ ".join([cols[i].ljust(widths[i]) for i in range(len(cols))]) + " │")
        print("╞═" + "═╪═".join(["═" * w for w in widths]) + "═╡")
        for row in rows:
            print("│ " + " │ ".join([str(v if v is not None else nullvalue).ljust(widths[i]) for i, v in enumerate(row)]) + " │")
        print("╰─" + "─┴─".join(["─" * w for w in widths]) + "─╯")
    else:
        # Fallback to list
        for row in rows:
            print(sep.join([str(v) if v is not None else nullvalue for v in row]))

def main():
    args = sys.argv[1:]
    options = {
        'mode': 'list', 'header': False, 'separator': '|',
        'nullvalue': '', 'filename': ':memory:', 'commands': [],
        'bail': False, 'echo': False,
    }

    i = 0
    while i < len(args):
        arg = args[i]
        if arg in ('-version', '--version'):
            print("3.54.0 2026-04-14 20:02:49 49b3bac482c831f503c7f90c35959e7ea731950e991baba86b2ab95987d2539b (64-bit)")
            return
        elif arg in ('-help', '--help'):
            print("Usage: ./executable [OPTIONS] [FILENAME [SQL...]]")
            return
        elif arg in ('-header', '--header'): options['header'] = True
        elif arg in ('-noheader', '--noheader'): options['header'] = False
        elif arg == '-csv': options['mode'] = 'csv'; options['separator'] = ','
        elif arg == '-json': options['mode'] = 'json'
        elif arg == '-column': options['mode'] = 'column'
        elif arg == '-table': options['mode'] = 'table'
        elif arg == '-box': options['mode'] = 'box'
        elif arg == '-list': options['mode'] = 'list'
        elif arg == '-separator':
